"""The images cua-bench runs: the canonical defaults and the benchmark images.

Each benchmark's Linux guest ships as two indexes linked by
``ai.cua.image.variants``: ``<ver>`` (rootfs: docker / gVisor) and
``<ver>-disk`` (containerDisk: QEMU / KubeVirt). ``BENCH_<NAME>`` pins the
rootfs index by digest (the one its lock file records); the resolver follows
its link to the disk index when ``--kind vm`` needs it. Override one for a
run with ``CUA_BENCH_IMAGE_<NAME>`` (e.g. ``CUA_BENCH_IMAGE_BENCH_WEB``) or
``--image``.
"""

from __future__ import annotations

import os

#: The default image per OS (``cua_image::canonical``), used when the SDK
#: cannot be loaded.
CANONICAL = {
    "linux": "ghcr.io/trycua/linux:24.04",
    "windows": "ghcr.io/trycua/windows:2022",
    "macos": "ghcr.io/trycua/macos:26",
}

#: Web benchmarks: MiniWoB, WebVoyager, Online-Mind2Web and WebGym tasks.
#: Guide: /cua-bench/guides/adapter-benchmarks#bench-web. Lock: libs/images/bench/web/lock.json.
#: Pinned to ghcr.io/trycua/bench-web:1.0-20261002-01636cb.
#: Floating ghcr.io/trycua/bench-web:1.0 (promoted: yes).
BENCH_WEB = "ghcr.io/trycua/bench-web@sha256:3b7e1d9d4e34694175cf1b44ffefc09b557c94b1c8f946fe50646d68df39ca87"

#: OSWorld-Verified: OSWorld Verified desktop tasks.
#: Guide: /cua-bench/guides/adapter-benchmarks#osworld-verified. Lock: libs/images/bench/osworld/lock.json.
#: Pinned to ghcr.io/trycua/bench-osworld:verified-20260924-93d6b29.
#: Floating ghcr.io/trycua/bench-osworld:verified (promoted: not yet).
BENCH_OSWORLD = "ghcr.io/trycua/bench-osworld@sha256:afe8e25fdda48cc71c60a6118a1bdfa0235352f311d27b271c5b7f5711f9001a"


def image(name: str) -> str:
    """``BENCH_WEB`` / ``BENCH_OSWORLD``, or its ``CUA_BENCH_IMAGE_<NAME>`` override."""
    default = globals()[name]
    return os.environ.get(f"CUA_BENCH_IMAGE_{name}", "").strip() or default


__all__ = ["CANONICAL", "BENCH_OSWORLD", "BENCH_WEB", "image"]
